"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week", "month": "month", "months": "month"}
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
TIME = r"[0-9]{2}:[0-9]{2}"
POSITIVE = r"[1-9][0-9]*"
DURATION = re.compile(rf"(?:({POSITIVE})d)?(?:({POSITIVE})h)?(?:({POSITIVE})m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    until: dt.date = None
    times: int = None


def parse_integer(word):
    # The grammar has no digit limit, unlike Python's int(string) conversion.
    return int(Decimal(word))


def parse_duration(word):
    """Return the elapsed minutes, or None for an invalid duration."""
    if not isinstance(word, str) or not word:
        return None
    match = DURATION.fullmatch(word.casefold())
    if match is None:
        return None
    days, hours, minutes = (parse_integer(part) if part else 0 for part in match.groups())
    return days * 1440 + hours * 60 + minutes


def format_duration(minutes):
    days, remainder = divmod(minutes, 1440)
    hours, minutes = divmod(remainder, 60)
    return "".join(f"{Decimal(value)}{unit}" for value, unit in
                   ((days, "d"), (hours, "h"), (minutes, "m")) if value)


def _count(word):
    return parse_integer(word) if re.fullmatch(POSITIVE, word) else None


def _date(word):
    return dt.date.fromisoformat(word) if re.fullmatch(DATE, word) else None


def _time(word):
    return dt.time.fromisoformat(word) if re.fullmatch(TIME, word) else None


def _month_day(word):
    if word == "last":
        return word
    if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        return int(word)
    return None


def _items(word, parse_item, sort_key=None):
    items = [parse_item(part) for part in word.split(",")]
    if None in items or len(set(items)) != len(items):
        return None
    return sorted(items, key=sort_key)


class _Words:
    def __init__(self, text):
        self.text = text
        self.tokens = iter(re.finditer(r"[^ \t]+", text))
        self.token = next(self.tokens, None)

    def peek(self):
        return self.token.group().casefold() if self.token else None

    def advance(self):
        self.token = next(self.tokens, None)

    def fail(self, expected):
        if self.token is None:
            message = f"expected {expected}, found end of rule"
            position = len(self.text)
        else:
            message = f"expected {expected}, found {self.token.group()!r}"
            position = self.token.start()
        raise RuleSyntaxError(message, position, text=self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            self.fail(repr(keyword))
        self.advance()

    def convert(self, what, parse):
        word = self.peek()
        if word is None:
            self.fail(what)
        try:
            value = parse(word)
        except ValueError:
            value = None
        if value is None:
            self.fail(what)
        self.advance()
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    words = _Words(text)
    rule = Rule()
    words.expect("every")
    word = words.peek()
    if word is not None and word not in UNITS:
        rule.every = words.convert("a count or unit", _count)
    rule.unit = words.convert("a unit", UNITS.get)
    if words.peek() == "on" and rule.unit != "day":
        words.advance()
        if rule.unit == "week":
            rule.on = words.convert("weekdays", lambda word: _items(word, WEEKDAYS.index))
        else:
            rule.on = words.convert("month days", lambda word: _items(
                word, _month_day, sort_key=lambda day: 32 if day == "last" else day))
    words.expect("at")
    rule.at = words.convert("times", lambda word: _items(word, _time))
    words.expect("for")
    rule.minutes = words.convert("a duration", parse_duration)
    words.expect("from")
    rule.start = words.convert("a date", _date)
    if words.peek() == "until":
        words.advance()

        def until_date(word):
            date = _date(word)
            return date if date is not None and date >= rule.start else None

        rule.until = words.convert("a date on or after 'from'", until_date)
    elif words.peek() == "times":
        words.advance()
        rule.times = words.convert("a count", _count)
    if words.peek() is not None:
        words.fail("end of rule")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    unit = rule.unit if rule.every == 1 else rule.unit + "s"
    out = ["every", str(Decimal(rule.every)), unit]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[day] for day in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(day) for day in rule.on)]
    out += ["at", ",".join(time.isoformat(timespec="minutes") for time in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    out += ["from", rule.start.isoformat()]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", str(Decimal(rule.times))]
    return " ".join(out)
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
import zoneinfo
from collections import defaultdict
from dataclasses import dataclass
from functools import lru_cache

from .errors import PlanError, RuleSyntaxError, describe_value
from .expand import candidates, local_instant
from .rules import DATE, TIME, Rule, parse_duration, parse_rule

LOCAL_DATETIME = rf"{DATE}T{TIME}"


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: zoneinfo.ZoneInfo
    priority: int


@dataclass
class Override:
    rule: RuleDef
    key: str
    start: int = None         # None for cancellations
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # (rule id, key) -> Override
    min_segment: int


@lru_cache(maxsize=1)
def _zone_names(_tzpath):
    # The search path is the cache key so a new path refreshes the names.
    return zoneinfo.available_timezones() - {"localtime"}


def _zone(name):
    if isinstance(name, str) and name in _zone_names(zoneinfo.TZPATH):
        # Exact membership keeps the spelling check independent of filesystem casing.
        try:
            return zoneinfo.ZoneInfo(name)
        except (ValueError, OSError, zoneinfo.ZoneInfoNotFoundError):
            pass
    raise PlanError(f"unknown timezone {describe_value(name)}")


def _load_rule(item, index, default_tz):
    if not isinstance(item, dict):
        raise PlanError(f"rule #{index} must be an object")
    rid = item.get("id")
    if not isinstance(rid, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
        raise PlanError(f"rule #{index} has an invalid id {describe_value(rid)}")
    try:
        rule = parse_rule(item.get("rule"))
        tz = _zone(item["timezone"]) if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError("priority must be an integer")
    except RuleSyntaxError as exc:
        raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text=exc.text) from exc
    except PlanError as exc:
        raise PlanError(f"rule {rid}: {exc}") from exc
    return RuleDef(index, rid, rule, tz, priority)


def _local_datetime(value):
    if not isinstance(value, str) or not re.fullmatch(LOCAL_DATETIME, value):
        raise ValueError
    return dt.datetime.fromisoformat(value)


def _load_override(item, rules):
    if not isinstance(item, dict):
        raise PlanError("override must be an object")
    rid = item.get("rule")
    if not isinstance(rid, str) or rid not in rules:
        raise PlanError(f"override for unknown rule {describe_value(rid)}")
    ruledef = rules[rid]
    key = item.get("key")
    if isinstance(key, str) and re.fullmatch(DATE, key) and len(ruledef.rule.at) == 1:
        key += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
    try:
        nominal = _local_datetime(key)
    except ValueError as exc:
        raise PlanError(f"rule {rid}: invalid override key {describe_value(key)}") from exc

    action = item.get("action")
    override = Override(ruledef, key)
    if action == "move":
        try:
            override.start = local_instant(_local_datetime(item.get("to")), ruledef.tz)
        except ValueError as exc:
            raise PlanError(f"rule {rid}: move override needs a valid 'to'") from exc
        override.minutes = ruledef.rule.minutes
        if "for" in item:
            override.minutes = parse_duration(item["for"])
            if override.minutes is None:
                raise PlanError(f"rule {rid}: invalid move duration {describe_value(item['for'])}")
    elif action != "cancel":
        raise PlanError(f"rule {rid}: unknown override action {describe_value(action)}")
    return override, nominal.date()


def _validate_keys(ruledef, dates_by_key):
    dates = set(dates_by_key.values())
    pending = set(dates_by_key)
    if ruledef.rule.times is None:
        # The override dates can be far apart. Expand each date independently.
        for day in dates:
            pending.difference_update(key for key, _ in candidates(ruledef, day, day))
    else:
        # Count from the rule's start only once, even for multiple overrides.
        for key, _ in candidates(ruledef, min(dates), max(dates)):
            pending.discard(key)
            if not pending:
                return
    if pending:
        raise PlanError(f"rule {ruledef.id}: override key {min(pending)!r} has no occurrence")


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    if not isinstance(raw.get("rules"), list):
        raise PlanError("rules must be a list")
    rules = {}
    for index, item in enumerate(raw["rules"]):
        ruledef = _load_rule(item, index, default_tz)
        if ruledef.id in rules:
            raise PlanError(f"rule {ruledef.id}: duplicate id")
        rules[ruledef.id] = ruledef

    raw_overrides = raw.get("overrides", [])
    if not isinstance(raw_overrides, list):
        raise PlanError("overrides must be a list")
    overrides = {}
    override_dates = defaultdict(dict)
    for item in raw_overrides:
        override, day = _load_override(item, rules)
        rid, key = override.rule.id, override.key
        if (rid, key) in overrides:
            raise PlanError(f"rule {rid}: duplicate override for {key!r}")
        overrides[rid, key] = override
        override_dates[rid][key] = day
    for rid, dates_by_key in override_dates.items():
        _validate_keys(rules[rid], dates_by_key)

    min_segment = 0
    if "min_segment" in raw:
        min_segment = parse_duration(raw["min_segment"])
        if min_segment is None:
            raise PlanError(f"invalid min_segment {describe_value(raw['min_segment'])}")
    return Plan(list(rules.values()), overrides, min_segment)
